/* eslint-disable */
// solve-challenge v1 — the store's challenge.ready (schema 1) request,
// verified before anything reads it. Every failure in this workflow THROWS:
// the Error Workflow sends the Telegram alert and the store, seeing no
// acknowledgement, retries the same item later. There is no in-flow failure
// rail.
//
// The signature covers the exact bytes the store sent (timestamp, event id and
// raw body joined by newlines, HMAC-SHA256 with N8N_SOLVE_CHALLENGE_SECRET), so
// the Webhook node must run with "Raw Body" on. Verification reads those bytes
// and never a re-serialised copy: PHP writes 1.0 where JavaScript writes 1,
// and escapes Arabic where JavaScript does not.
//
// Keys and secrets live in the Config node (Edit Fields) that sits between
// the Webhook and this node - the instance has neither environment variables
// nor $vars (owner decision, 2026-09-14). A value still reading CONFIGURE_...
// is a value nobody pasted.

const crypto = require('crypto');

const config = $('Config').first().json || {};
const requiredKeys = [
    'N8N_SOLVE_CHALLENGE_KEY',
    'N8N_SOLVE_CHALLENGE_SECRET',
    'N8N_FULFILLMENT_KEY',
    'N8N_FULFILLMENT_SECRET',
    'FFT_API_USER',
    'FFT_API_KEY',
];
const missingKeys = requiredKeys.filter((name) => !config[name] || /^CONFIGURE_/.test(String(config[name])));
if (missingKeys.length) {
    throw new Error(
        `[verify] not set in the Config node: ${missingKeys.join(', ')}`,
    );
}
if (String(config.N8N_SOLVE_CHALLENGE_SECRET).length < 32) {
    throw new Error('[verify] N8N_SOLVE_CHALLENGE_SECRET is shorter than 32 characters');
}

// Read from the Webhook node by name: the Config node sits in between and
// passes the request through, but the raw bytes are authoritative here.
const item = $('Webhook').first();
const json = item.json || {};
const headers = json.headers || {};

function header(name) {
    const value = headers[name] ?? headers[name.toLowerCase()];
    return String(Array.isArray(value) ? value[0] : value ?? '');
}

function equal(left, right) {
    const a = Buffer.from(String(left), 'utf8');
    const b = Buffer.from(String(right), 'utf8');
    return a.length === b.length && crypto.timingSafeEqual(a, b);
}

// The raw body. In n8n's default (memory) binary mode the Webhook node hands
// it over base64-encoded under binary.data.data; the filesystem mode hands a
// file id instead, which the helper below resolves when it exists (it reads
// this node's input, so the Config node must keep "Include Binary" on).
async function rawBody() {
    const helpers = typeof this === 'object' && this !== null ? this.helpers : null;
    if (helpers && typeof helpers.getBinaryDataBuffer === 'function') {
        try {
            const buffer = await helpers.getBinaryDataBuffer(0, 'data');
            if (buffer && buffer.length) return buffer.toString('utf8');
        } catch (error) {
            // fall through to the in-memory shape
        }
    }
    const binary = item.binary && item.binary.data;
    if (binary && binary.id) {
        // Stored outside memory and the helper could not read it: the
        // in-memory field holds a mode marker, not the bytes.
        return null;
    }
    if (binary && typeof binary.data === 'string' && binary.data !== '') {
        return Buffer.from(binary.data, 'base64').toString('utf8');
    }
    if (typeof json.rawBody === 'string') return json.rawBody;
    return null;
}

const raw = await rawBody.call(this);
if (raw === null) {
    throw new Error(
        '[verify] the raw request body is unavailable - turn on "Raw Body" in the Webhook node options',
    );
}

const key = header('x-arabut-key');
const timestamp = header('x-arabut-timestamp');
const eventId = header('x-arabut-event');
const signature = header('x-arabut-signature');

if (!equal(key, config.N8N_SOLVE_CHALLENGE_KEY)) {
    throw new Error('[verify] X-ArabUT-Key does not match N8N_SOLVE_CHALLENGE_KEY');
}
if (!/^\d{10}$/.test(timestamp) || Math.abs(Math.floor(Date.now() / 1000) - Number(timestamp)) > 300) {
    throw new Error('[verify] X-ArabUT-Timestamp is outside the five-minute window');
}
const expected = crypto
    .createHmac('sha256', config.N8N_SOLVE_CHALLENGE_SECRET)
    .update(`${timestamp}\n${eventId}\n${raw}`)
    .digest('hex');
if (!equal(signature, expected)) {
    throw new Error('[verify] X-ArabUT-Signature does not match the request body');
}

let event;
try {
    event = JSON.parse(raw);
} catch (error) {
    throw new Error('[verify] the request body is not JSON');
}

if (!event || event.eventType !== 'challenge.ready') {
    throw new Error(`[verify] unexpected eventType ${event && event.eventType}`);
}
if (Number(event.schemaVersion) !== 1) {
    throw new Error(`[verify] unexpected schemaVersion ${event && event.schemaVersion}; this workflow reads schema 1`);
}
if (event.eventId !== eventId) {
    throw new Error('[verify] X-ArabUT-Event does not match the body eventId');
}
const request = event.data;
const challenge = request && request.item;
const account = challenge && challenge.account;
if (!request || typeof request.order_number !== 'string' || !challenge || typeof challenge.order_item_public_id !== 'string') {
    throw new Error('[verify] the request names no order item');
}
if (challenge.service !== 'sbc' || !challenge.sbc || !(Number(challenge.sbc.set_id) > 0)) {
    throw new Error(`[verify] order ${request.order_number}: the item is not a challenge with a set id`);
}
if (challenge.supplier_platform !== 'PS' && challenge.supplier_platform !== 'PC') {
    throw new Error(`[verify] order ${request.order_number}: platform ${challenge.supplier_platform || '?'} has no solver`);
}
if (!account || typeof account.ea_email !== 'string' || account.ea_email === '' || !account.ea_password) {
    throw new Error(`[verify] order ${request.order_number}: the item carries no EA account`);
}

return [{ json: { eventId, request, receivedAt: new Date().toISOString() } }];

/* eslint-disable */
// solve-challenge v1 — the "set exists and is priced" half of v14's
// "SBC: Match & Validate", run again before the solve.
//
// ship-coins already refused an unpriced challenge when it bought the coins;
// it is checked again here because a set can expire between the two phases,
// and v14 submitted nothing FFT would not price. The messages are v14's, so
// the alert reads as it always did. The coin arithmetic is not here: the
// coins are bought, and the solve is priced by FFT itself.

// ── 1. إعادة بناء مصفوفة التحديات من كل عناصر الـ input ──
const allInputItems = $input.all();
let availableSBCs = null;

if (allInputItems.length > 1) {
  availableSBCs = allInputItems.map(item => item.json);
}
if (!availableSBCs && allInputItems.length === 1) {
  const firstJson = allInputItems[0].json;
  if (Array.isArray(firstJson)) availableSBCs = firstJson;
  else if (firstJson.data && Array.isArray(firstJson.data)) availableSBCs = firstJson.data;
  else if (firstJson.sbcs && Array.isArray(firstJson.sbcs)) availableSBCs = firstJson.sbcs;
}
if (!availableSBCs && allInputItems.length === 1) {
  const firstJson = allInputItems[0].json;
  if (firstJson.setID !== undefined) availableSBCs = [firstJson];
}

const request = $('Verify Request').first().json.request;
const orderId = request.order_number;
const item = request.item;

if (!availableSBCs || !Array.isArray(availableSBCs) || availableSBCs.length === 0) {
  throw new Error(`[sbc] order ${orderId}: فشل قراءة قائمة التحديات. عدد العناصر المستقبلة: ${allInputItems.length}`);
}

const platform = item.supplier_platform || 'PS';
const setID = Number(item.sbc.set_id);
const sbcMatch = availableSBCs.find(sbc => Number(sbc.setID) === setID);
if (!sbcMatch) throw new Error(`[sbc] order ${orderId}: التحدي غير موجود: setID ${setID}`);

const coinPrice = platform === 'PC'
  ? parseFloat(sbcMatch.pcPrice)
  : parseFloat(sbcMatch.consolePrice);

if (!coinPrice || coinPrice <= 0) {
  const rawPrice = platform === 'PC' ? sbcMatch.pcPrice : sbcMatch.consolePrice;
  throw new Error(`[sbc] order ${orderId}: FFT ما مسعّر هذا التحدي حالياً (السعر المستلم: ${rawPrice}) — غالباً غير قابل للحل الآلي: "${sbcMatch.sbcName}" [منصة ${platform}]. الطلب يحتاج حل يدوي.`);
}

// v14's "SBC: Split SBC IDs" item, for one set: what "SBC: Submit Solve" reads.
return [{
  json: {
    orderId,
    orderItemPublicId: item.order_item_public_id,
    setID: sbcMatch.setID,
    sbcName: sbcMatch.sbcName,
    challengeAmount: sbcMatch.challengeAmount,
    expiry: sbcMatch.expiry,
    coinsPerSolveK: Math.ceil(coinPrice / 1000),
    timesToSolve: Math.max(1, Number(item.sbc.times_to_solve) || 1),
    platform,
    eaEmail: item.account.ea_email,
    customerName: request.customer_name || '',
    funding: item.funding || null,
    totalSBCsFound: availableSBCs.length,
  },
}];

/* eslint-disable */
// solve-challenge v1 — the solve ids FFT issued, as the placement report.
//
// v14's "SBC: Solve Accepted?" and the id-collecting half of
// "SBC Solve: Prepare Poll" in one place. newSBCAPI answers a list (one entry
// per solve), sometimes as a JSON string under `data`, each entry carrying
// `status` and `sbcSolveID`. Anything but a first entry with status
// "processed" is a rejection - v14's alert said the usual cause is that FFT
// has no customer under that email, which the corrected-email path now
// avoids - and it throws, so the ops alert names the order and the store
// retries the item later.
//
// One report row, challenge phase: the first solve id is the reference and
// every id is listed, the way the store's placement endpoint takes them.

const solve = $('Validate Set').first().json;
const orderId = solve.orderId;

const answer = $input.first().json || {};
let parsed;
try {
  parsed = typeof answer.data === 'string' ? JSON.parse(answer.data) : (answer.data || answer);
} catch (e) {
  throw new Error(`[solve] order ${orderId}: FFT رجّع رد غير مقروء: ${String(answer.data).slice(0, 200)}`);
}
const entries = Array.isArray(parsed) ? parsed : [parsed];
const first = entries[0];

if (!first || first.status !== 'processed') {
  const detail = (first && (first.error || first.message || first.status)) || (parsed && (parsed.error || parsed.message)) || JSON.stringify(parsed).slice(0, 300);
  throw new Error(`[solve] order ${orderId}: FFT رفض تقديم التحدي "${solve.sbcName}": ${detail} — غالباً ما فيه عميل بهذا الإيميل عند FFT`);
}

const ids = entries
  .map((entry) => entry && entry.sbcSolveID)
  .filter((id) => id !== undefined && id !== null && String(id) !== '')
  .map((id) => String(id));

if (ids.length === 0) {
  throw new Error(`[solve] order ${orderId}: FFT قبل التحدي بدون رقم حل (sbcSolveID)`);
}

return [{
  json: {
    orderId,
    order_item_public_id: solve.orderItemPublicId,
    supplier: 'fft',
    supplier_order_id: ids[0],
    delivery_phase: 'challenge',
    challenge_ids: ids,
  },
}];

/* eslint-disable */
// solve-challenge v1 — the signed placement report for the solve.
//
// The store verifies HMAC-SHA256 over `timestamp\neventId\nrawBody` with
// N8N_FULFILLMENT_SECRET (VerifyN8nFulfillmentSignature). rawBody is the
// exact byte sequence that is signed AND the exact byte sequence the HTTP
// node sends raw, so the signature cannot drift from the payload. Same node
// as ship-coins', plus the challenge ids the challenge phase requires.

const crypto = require('crypto');
const secret = $('Config').first().json.N8N_FULFILLMENT_SECRET;
if (!secret || /^CONFIGURE_/.test(String(secret)) || String(secret).length < 32) {
    throw new Error('[report] N8N_FULFILLMENT_SECRET is not set in the Config node or shorter than 32 characters');
}

const ALPHABET = '0123456789ABCDEFGHJKMNPQRSTVWXYZ';
function ulid() {
    let time = Date.now();
    let timestamp = '';
    for (let index = 0; index < 10; index += 1) {
        timestamp = ALPHABET[time % 32] + timestamp;
        time = Math.floor(time / 32);
    }
    let random = '';
    for (let index = 0; index < 16; index += 1) {
        random += ALPHABET[Math.floor(Math.random() * ALPHABET.length)];
    }
    return timestamp + random;
}

return $input.all().map(({ json }) => {
    const report = {
        order_item_public_id: json.order_item_public_id,
        supplier: json.supplier,
        supplier_order_id: json.supplier_order_id,
        delivery_phase: json.delivery_phase,
        challenge_ids: json.challenge_ids,
    };
    const rawBody = JSON.stringify(report);
    const timestamp = String(Math.floor(Date.now() / 1000));
    const event = ulid();
    const signature = crypto
        .createHmac('sha256', secret)
        .update(`${timestamp}\n${event}\n${rawBody}`)
        .digest('hex');

    return { json: { ...json, rawBody, timestamp, event, signature } };
});

/* eslint-disable */
// solve-challenge v1 — the placement report must have landed, then the
// answer for the store.
//
// The report HTTP node runs with neverError + fullResponse, so a refused
// report reaches this node as data rather than as an unhandled node error.
// Anything but 200 with acknowledged:true throws: the solve was submitted at
// FFT and the store does not know - the exact case the ops alert is for, and
// the case the store's retry then repairs, since the report endpoint is
// idempotent and a second run reports the same solve ids again.

const solve = $('Validate Set').first().json;
const orderId = solve.orderId;
const responses = $input.all();

if (responses.length !== 1) {
    throw new Error(`[report] order ${orderId}: ${responses.length} report(s) answered for one challenge`);
}

function decode(body) {
    if (body == null) return {};
    if (typeof body === 'string') { try { return JSON.parse(body); } catch (e) { return { raw: body }; } }
    return body;
}

const { json } = responses[0];
const status = Number(json.statusCode || 0);
const body = decode(json.body);
const data = body && body.data;

if (!(status === 200 && data && data.acknowledged === true)) {
    const error = (body && body.error) || {};
    throw new Error(`[report] order ${orderId}: the store refused the placement report (HTTP ${status} ${error.code || ''} ${error.message || body.message || ''})`.trim());
}

return [{
    json: {
        acknowledged: true,
        placed: {
            order_item_public_id: data.order_item_public_id,
            supplier: data.supplier,
            supplier_order_id: data.supplier_order_id,
            job_public_id: data.job_public_id,
        },
        orderId,
    },
}];
